create or replace TABLE LDL_DATA_PRODUCTION.CORE_DIM.T_FACT_RETAIL_GROWTH_BY_STORE_DAY_1 (
	BUS_DT DATE NOT NULL COMMENT 'The business date to which the measures are related.',
	INT_ORG_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the internal organization.',
	INT_ORG_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the discriminators for internal organizations.',
	COUNTRY_ORG_CD VARCHAR(2) NOT NULL COMMENT 'The code of the business country_1 for which the related country_1 organization is responsible. (The business country_1 is not identical to a political country.)',
	PERF_ADJ_SALES_CNT NUMBER(38,0) COMMENT 'The number of sales_1 variants which were sold in the given store on the given day. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Weight-based products are not included.)',
	PERF_ADJ_SALES_BYTD_CNT NUMBER(38,0) COMMENT 'The business-year-to-date sum of the number of sales_1 variants which have been sold in that store up to the given day. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Weight-based products are not included.)',
	PERF_ADJ_SALES_PY_CNT NUMBER(38,0) COMMENT 'The number of sales_1 variants which were sold in that store on the same calendar_1 date one year ago. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Weight-based products are not included.)',
	PERF_ADJ_SALES_PY_BYTD_CNT NUMBER(38,0) COMMENT 'The business-year-to-date sum of the number of sales_1 variants which have been sold in that store up to the same calendar_1 date one year ago. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Weight-based products are not included.)',
	PERF_ADJ_SALES_PY_SWDAY_CNT NUMBER(38,0) COMMENT 'The number of sales_1 variants which were sold in that store on the same weekday one year ago. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Weight-based products are not included.)',
	PERF_ADJ_SALES_PY_SWDAY_BYTD_CNT NUMBER(38,0) COMMENT 'The business-year-to-date sum of the number of sales_1 variants which have been sold in that store up to the same weekday one year ago. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Weight-based products are not included.)',
	PERF_ADJ_SALES_QTY NUMBER(38,5) COMMENT 'The total quantity of weight-based products which have been sold in the given store on the given day. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Quantity in the unit_1 defined by the unit_1 of measure code)',
	PERF_ADJ_SALES_BYTD_QTY NUMBER(38,5) COMMENT 'The business-year-to-date sum of the quantity of weight-based products which have been sold in that store up to the given day. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Quantity in the unit_1 defined by the unit_1 of measure code)',
	PERF_ADJ_SALES_PY_QTY NUMBER(38,5) COMMENT 'The total quantity of weight-based products which were sold in that store on the same calendar_1 date one year ago. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Quantity in the unit_1 defined by the unit_1 of measure code)',
	PERF_ADJ_SALES_PY_BYTD_QTY NUMBER(38,5) COMMENT 'The business-year-to-date sum of the quantity of weight-based products which have been sold in that store up to the same calendar_1 date one year ago. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Quantity in the unit_1 defined by the unit_1 of measure code)',
	PERF_ADJ_SALES_PY_SWDAY_QTY NUMBER(38,5) COMMENT 'The total quantity of weight-based products which were sold in that store on the same weekday date one year ago. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Quantity in the unit_1 defined by the unit_1 of measure code)',
	PERF_ADJ_SALES_PY_SWDAY_BYTD_QTY NUMBER(38,5) COMMENT 'The business-year-to-date sum of the quantity of weight-based products  which have been sold in that store up to the same weekday one year ago. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Quantity in the unit_1 defined by the unit_1 of measure code)',
	PERF_ADJ_RETURN_CNT NUMBER(38,0) COMMENT 'The number of sales_1 variant which were returned in the given store on the given day. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Weight-based products are not included.)',
	PERF_ADJ_RETURN_BYTD_CNT NUMBER(38,0) COMMENT 'The business-year-to-date sum of the number of sales_1 variants which have been returned in that store up to the given day. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Weight-based products are not included.)',
	PERF_ADJ_RETURN_PY_CNT NUMBER(38,0) COMMENT 'The number of sales_1 variants which were returned in that store on the same calendar_1 date one year ago. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Weight-based products are not included.)',
	PERF_ADJ_RETURN_PY_BYTD_CNT NUMBER(38,0) COMMENT 'The business-year-to-date sum of the number of sales_1 variants which have been returned in that store up to the same calendar_1 date one year ago. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Weight-based products are not included.)',
	PERF_ADJ_RETURN_PY_SWDAY_CNT NUMBER(38,0) COMMENT 'The number of sales_1 variants which were returned in that store on the same weekday one year ago. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Weight-based products are not included.)',
	PERF_ADJ_RETURN_PY_SWDAY_BYTD_CNT NUMBER(38,0) COMMENT 'The business-year-to-date sum of the number of sales_1 variants which have been returned in that store up to the same weekday one year ago. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Weight-based products are not included.)',
	PERF_ADJ_RETURN_QTY NUMBER(38,5) COMMENT 'The total quantiy of weight-based products which were returned in the given store on the given day. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Quantity in the unit_1 defined by the unit_1 of measure code)',
	PERF_ADJ_RETURN_BYTD_QTY NUMBER(38,5) COMMENT 'The business-year-to-date sum of the quantity of weight-based products which have been returned in that store up to the given day. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Quantity in the unit_1 defined by the unit_1 of measure code)',
	PERF_ADJ_RETURN_PY_QTY NUMBER(38,5) COMMENT 'The total quantity of weight-based products which were returned in that store on the same calendar_1 date one year ago. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Quantity in the unit_1 defined by the unit_1 of measure code)',
	PERF_ADJ_RETURN_PY_BYTD_QTY NUMBER(38,5) COMMENT 'The business-year-to-date sum of the quantity of weight-based products which have been returned in that store up to the same calendar_1 date one year ago. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Quantity in the unit_1 defined by the unit_1 of measure code)',
	PERF_ADJ_RETURN_PY_SWDAY_QTY NUMBER(38,5) COMMENT 'The total quantity of weight-based products which were returned in that store on the same weekday date one year ago. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Quantity in the unit_1 defined by the unit_1 of measure code)',
	PERF_ADJ_RETURN_PY_SWDAY_BYTD_QTY NUMBER(38,5) COMMENT 'The business-year-to-date sum of the quantity of weight-based products  which have been returned in that store up to the same weekday one year ago. Only product variants with an international item_1 group or commission products with an absolute unit_1 price not between 0.0001 and 0.0315 EUR are considered. (Quantity in the unit_1 defined by the unit_1 of measure code)',
	UOM_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the unit_1 of measure, such as kg, meter or pieces.',
	TURNOVER_NET_VAL NUMBER(38,5) COMMENT 'The net turnover which was generated for that store on the given day. (This is the consolidated amount after applying the priority logic. The turnover is the difference of sales_1 and returns.)',
	TURNOVER_BYTD_NET_VAL NUMBER(38,5) COMMENT 'The business-year-to-date sum of the net turnover for that store up to the given day. (This is the consolidated amount after applying the priority logic. The turnover is the difference of sales_1 and returns.)',
	TURNOVER_PY_NET_VAL NUMBER(38,5) COMMENT 'The net turnover which was generated for that store on the same calendar_1 date one year ago. (This is the consolidated amount after applying the priority logic. The turnover is the difference of sales_1 and returns.)',
	TURNOVER_PY_BYTD_NET_VAL NUMBER(38,5) COMMENT 'The business-year-to-date sum of the net turnover for that store up to the same calendar_1 date one year ago. (This is the consolidated amount after applying the priority logic. The turnover is the difference of sales_1 and returns.)',
	TURNOVER_PY_SWDAY_NET_VAL NUMBER(38,5) COMMENT 'The net turnover which was generated for that store on the same weekday one year ago. (This is the consolidated amount after applying the priority logic. The turnover is the difference of sales_1 and returns.)',
	TURNOVER_PY_SWDAY_BYTD_NET_VAL NUMBER(38,5) COMMENT 'The business-year-to-date sum of the net turnover for that store up to the same weekday one year ago. (This is the consolidated amount after applying the priority logic. The turnover is the difference of sales_1 and returns.)',
	CURR_CD VARCHAR(3) NOT NULL COMMENT 'The code identifying the currency according to ISO-4217.',
	RECEIPT_CNT NUMBER(38,0) COMMENT 'The number of sales_1 transactions (i.e. the number of receipts) which have been performed in that store on the given day. (This is the consolidated amount after applying the priority logic.)',
	RECEIPT_BYTD_CNT NUMBER(38,0) COMMENT 'The business-year-to-date sum of the number of sales_1 transactions (i.e. the number of receipts) which have been performed in that store up to the given day. (This is the consolidated amount after applying the priority logic.)',
	RECEIPT_PY_CNT NUMBER(38,0) COMMENT 'The number of sales_1 transactions (i.e. the number of receipts) which have been performed in that store on the same calendar_1 date one year ago. (This is the consolidated amount after applying the priority logic.)',
	RECEIPT_PY_BYTD_CNT NUMBER(38,0) COMMENT 'The business-year-to-date sum of the number of sales_1 transactions (i.e. the number of receipts) which have been performed in that store up to the same calendar_1 date one year ago. (This is the consolidated amount after applying the priority logic.)',
	RECEIPT_PY_SWDAY_CNT NUMBER(38,0) COMMENT 'The number of sales_1 transactions (i.e. the number of receipts) which have been performed in that store on the same weekday one year ago. (This is the consolidated amount after applying the priority logic.)',
	RECEIPT_PY_SWDAY_BYTD_CNT NUMBER(38,0) COMMENT 'The business-year-to-date sum of the number of sales_1 transactions (i.e. the number of receipts) which have been performed in that store up to the same weekday one year ago. (This is the consolidated amount after applying the priority logic.)',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	constraint PK_T_FACT_RETAIL_GROWTH_BY_STORE_DAY primary key (BUS_DT, INT_ORG_SID)
) WITH ROW ACCESS POLICY #unknown_policy
COMMENT='An aggregate fact holding basic retail measures per store and day. This includes sales_1 and return volume, net turnover and receipt count. The goal of this fact table is to analyze growth. That portion of the growth that is caused purely by the increase in  the number of stores, shall be excluded. (bereinigte Steigerung) The goal is to compare the same set of stores in the current year and in the previous year. So this fact table does not  contain measures for the first year after the opening of a store. To be specific, it starts with the Monday following the day one year after the opening of the store, and it ends on the Sunday after the closing of the store. Note that the base measure in this table are identical to the measures in the store day aggregate, however, derived measures, in particular the year-to-date sums, are different.'
;